import { Component, OnInit, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';

@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.css'],
})
export class NavbarComponent implements OnInit, OnDestroy {
  isLoggedIn = false;
  username = '';
  userRole: string = '';
  cartCount = 0;
  private intervalId: any;

  constructor(
    private router: Router,
    private cdr: ChangeDetectorRef,
  ) {}

  ngOnInit(): void {
    this.checkLoginStatus();

    // Listen for route changes
    this.router.events
      .pipe(filter((event) => event instanceof NavigationEnd))
      .subscribe(() => {
        this.checkLoginStatus();
        this.cdr.detectChanges();
      });

    // 🔴 ADD THIS: Check every 500ms for changes
    this.intervalId = setInterval(() => {
      const previousState = this.isLoggedIn;
      this.checkLoginStatus();
      if (previousState !== this.isLoggedIn) {
        console.log('Login state changed detected by interval');
        this.cdr.detectChanges();
      }
    }, 500);
  }

  ngOnDestroy(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }
  }

  checkLoginStatus(): void {
    const user = localStorage.getItem('username');
    const token = localStorage.getItem('token');
    const role = localStorage.getItem('role');

    // Check if user is logged in
    this.isLoggedIn = !!(user && user !== 'null' && user !== '' && token);
    this.username = user || '';
    this.userRole = role || '';

    if (this.isLoggedIn) {
      this.loadCartCount();
    }
  }

  loadCartCount(): void {
    try {
      const cart = JSON.parse(localStorage.getItem('cart') || '[]');
      this.cartCount = cart.length;
    } catch (e) {
      this.cartCount = 0;
    }
  }

  logout(): void {
    if (confirm('Are you sure you want to logout?')) {
      // Clear all user data
      localStorage.clear();

      // Reset state
      this.isLoggedIn = false;
      this.username = '';
      this.userRole = '';
      this.cartCount = 0;

      alert('Logged out successfully! 👋');

      // 🔴 Force page reload
      window.location.reload();
    }
  }
}
<mat-toolbar color="primary" class="navbar">
  <div class="logo-container">
    <span class="logo-icon">🛒</span>
    <span class="logo">QuickMart </span>
  </div>

  <span class="spacer"></span>

  <div class="nav-links">
    <!-- Common links for everyone -->
    <a mat-button routerLink="/home" routerLinkActive="active-link">
      <mat-icon>home</mat-icon>
      Home
    </a>

    <a mat-button routerLink="/about" routerLinkActive="active-link">
      <mat-icon>info</mat-icon>
      About
    </a>

    <a mat-button routerLink="/contact" routerLinkActive="active-link">
      <mat-icon>contact_mail</mat-icon>
      Contact
    </a>

    <!-- 🔴 Show Login/Register ONLY when NOT logged in -->
    <ng-container *ngIf="!isLoggedIn">
      <a mat-button routerLink="/login" routerLinkActive="active-link">
        <mat-icon>login</mat-icon>
        Login
      </a>

      <a mat-button routerLink="/register" routerLinkActive="active-link">
        <mat-icon>person_add</mat-icon>
        Register
      </a>
    </ng-container>

    <!-- 🟢 Show User/Admin Menu ONLY when logged in -->
    <ng-container *ngIf="isLoggedIn">
      <!-- Admin specific links -->
      <ng-container *ngIf="userRole === 'ADMIN'">
        <a
          mat-button
          routerLink="/admin/dashboard"
          routerLinkActive="active-link"
        >
          <mat-icon>dashboard</mat-icon>
          Dashboard
        </a>
        <a
          mat-button
          routerLink="/admin/products"
          routerLinkActive="active-link"
        >
          <mat-icon>inventory</mat-icon>
          Products
        </a>
        <a mat-button routerLink="/admin/orders" routerLinkActive="active-link">
          <mat-icon>shopping_cart</mat-icon>
          Orders
        </a>
      </ng-container>

      <!-- User specific links -->
      <ng-container *ngIf="userRole === 'USER'">
        <a mat-button routerLink="/user/items" routerLinkActive="active-link">
          <mat-icon>store</mat-icon>
          Shop
        </a>
      </ng-container>

      <!-- User Menu Dropdown (common for both) -->
      <button mat-button [matMenuTriggerFor]="userMenu" class="user-menu-btn">
        <mat-icon>account_circle</mat-icon>
        {{ username }}
        <mat-icon>arrow_drop_down</mat-icon>
      </button>

      <mat-menu #userMenu="matMenu">
        <button mat-menu-item routerLink="/profile">
          <mat-icon>account_box</mat-icon>
          My Profile
        </button>
        <button mat-menu-item routerLink="/orders">
          <mat-icon>shopping_bag</mat-icon>
          My Orders
        </button>
        <button mat-menu-item routerLink="/cart">
          <mat-icon>shopping_cart</mat-icon>
          Cart
          <span class="cart-count" *ngIf="cartCount > 0">{{ cartCount }}</span>
        </button>
        <button mat-menu-item routerLink="/wishlist">
          <mat-icon>favorite</mat-icon>
          Wishlist
        </button>
        <mat-divider></mat-divider>
        <button mat-menu-item (click)="logout()" class="logout-item">
          <mat-icon>exit_to_app</mat-icon>
          Logout
        </button>
      </mat-menu>
    </ng-container>
  </div>
</mat-toolbar>
